<?php
declare(strict_types=1);namespace QualitySystem\Tests;use PHPUnit\Framework\TestCase;
final class ConsultancyCommitteeWorkflowTest extends TestCase{public function testWorkflowEndpointIsProtectedAndCsrfEnabled():void{$s=file_get_contents(dirname(__DIR__).'/consultancy_committee.php');$this->assertStringContainsString("require_once __DIR__.'/auth_check.php'",$s);$this->assertStringContainsString('csrfField()',$s);$this->assertStringContainsString("Participant Review",$s);$this->assertStringContainsString("Committee Head Review",$s);$this->assertStringContainsString("Department Head Review",$s);}public function testApprovalCannotBeImpersonated():void{$s=file_get_contents(dirname(__DIR__).'/consultancy_committee.php');$this->assertStringContainsString('staff_id=:staff',$s);$this->assertStringContainsString('currentStaffId',$s);$this->assertStringContainsString('signed half-plus-one quorum',$s);}public function testAttendanceRequiresOwnSignatureAndHeadCertification():void{$s=file_get_contents(dirname(__DIR__).'/consultancy_attendance_approval.php');$this->assertStringContainsString('floor($invited/2)+1',$s);$this->assertStringContainsString('staff_id=:staff',$s);$this->assertStringContainsString('Only the appointed committee head may certify attendance.',$s);$workflow=file_get_contents(dirname(__DIR__).'/consultancy_committee.php');$this->assertStringContainsString('attendance_approved_at',$workflow);}public function testConsultancyCommitteeIsInNavigation():void{$s=file_get_contents(dirname(__DIR__).'/nav.php');$this->assertStringContainsString('/consultancy_committee.php',$s);}}
